WITH v(subject, exam_board, level, topic_id, topic_name, front, back, ord) AS (VALUES
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What are the steps of proof by induction?', 'Basis (show true for n = 1), assumption (assume true for n = k), inductive step (show true for n = k + 1), conclusion.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What should the conclusion of an induction proof state?', 'If true for n = k, it is true for n = k + 1; since it is true for n = 1, it is true for all positive integers n.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove Σ r from 1 to n = n(n + 1)/2 by induction: what is the inductive step?', 'Assume Σ to k = k(k + 1)/2. Then Σ to k + 1 = k(k + 1)/2 + (k + 1) = (k + 1)(k + 2)/2.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How is induction used for divisibility?', 'Show f(1) is divisible by m, then write f(k + 1) in terms of f(k) plus a multiple of m.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove 6ⁿ − 1 is divisible by 5 for n ≥ 1.', 'n = 1: 5. Assume 6ᵏ − 1 = 5m. Then 6^(k+1) − 1 = 6(6ᵏ − 1) + 5 = 30m + 5, divisible by 5.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove 3^(2n) − 1 is divisible by 8.', 'n = 1: 8. Assume 9ᵏ − 1 = 8m. Then 9^(k+1) − 1 = 9(9ᵏ − 1) + 8 = 72m + 8.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How is induction used for matrices?', 'Show the formula for Mⁿ holds for n = 1, then multiply Mᵏ by M to get the formula for M^(k+1).', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove by induction that (1 1; 0 1)ⁿ = (1 n; 0 1).', 'n = 1 is true. Assume true for k; then (1 k; 0 1)(1 1; 0 1) = (1 k + 1; 0 1).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How is induction used for recurrence relations?', 'Show the closed form matches u₁, then use the recurrence with the assumption to show it holds for u_(k+1).', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove uₙ = 2ⁿ − 1 if u₁ = 1, u_(n+1) = 2uₙ + 1.', 'n = 1: 1. Assume u_k = 2ᵏ − 1. Then u_(k+1) = 2(2ᵏ − 1) + 1 = 2^(k+1) − 1.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How is induction used for derivatives?', 'Show the formula for the n-th derivative holds for n = 1, then differentiate the k-th to get the (k + 1)-th.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that d^n/dx^n (x eˣ) = (x + n)eˣ.', 'n = 1: (x + 1)eˣ. Assume true for k; differentiating (x + k)eˣ gives (x + k + 1)eˣ.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Why is the basis step necessary?', 'Without it, the chain of implications has no starting point.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Why is the inductive step alone not enough?', 'It only shows "if true for k then true for k + 1", not that it is ever true.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Can induction start from a value other than 1?', 'Yes; the basis can be any integer, and the result holds for all integers from there.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What is a common error in induction proofs?', 'Assuming the result for k + 1 instead of deriving it, or omitting the conclusion.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove Σ r² = n(n + 1)(2n + 1)/6: what must be shown in the inductive step?', 'k(k + 1)(2k + 1)/6 + (k + 1)² = (k + 1)(k + 2)(2k + 3)/6.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that 2ⁿ > n for all n ≥ 1.', 'n = 1: 2 > 1. Assume 2ᵏ > k. Then 2^(k+1) = 2 × 2ᵏ > 2k ≥ k + 1 for k ≥ 1.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How is induction used for inequalities?', 'Use the assumption and then show the next case satisfies the inequality, often using extra algebraic steps.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove n³ − n is divisible by 6 using induction.', 'n = 1: 0. (k + 1)³ − (k + 1) = (k³ − k) + 3k(k + 1); k(k + 1) is even, so 3k(k + 1) is a multiple of 6.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What is the key idea of induction?', 'Like dominoes: if the first falls and each one knocks over the next, all fall.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What is proof by exhaustion compared with induction?', 'Exhaustion checks a finite number of cases; induction proves infinitely many.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Can induction prove statements about all real numbers?', 'No, only about integers (or well-ordered sets).', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove 7ⁿ − 3ⁿ is divisible by 4.', 'n = 1: 4. 7^(k+1) − 3^(k+1) = 7(7ᵏ − 3ᵏ) + 4 × 3ᵏ, divisible by 4.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What should you write for the assumption step?', '"Assume the statement is true for n = k", then write out the statement with k.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'How do you prove a sum formula for Σ r(r + 1)?', 'Basis with n = 1, assume for k, add (k + 1)(k + 2), and factorise.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Why must the final result be clearly shown to match the formula with k + 1?', 'To demonstrate that the statement holds for n = k + 1.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'What does "for all n ∈ ℤ⁺" mean?', 'For all positive integers n.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Prove that 4ⁿ + 6n − 1 is divisible by 9.', 'n = 1: 9. f(k + 1) − 4f(k) = 6(k + 1) − 1 − 24k + 4 = −18k + 9, a multiple of 9.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.1', 'Proof', 'Why might f(k + 1) − f(k) be useful in divisibility proofs?', 'If it is divisible by m and f(k) is, then so is f(k + 1).', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is i?', 'The imaginary unit, defined by i² = −1.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is a complex number?', 'A number of the form z = a + bi, where a and b are real.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What are Re(z) and Im(z) for z = 3 − 4i?', 'Re(z) = 3 and Im(z) = −4.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is the complex conjugate of z = a + bi?', 'z* = a − bi.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Simplify i³ and i⁴.', 'i³ = −i and i⁴ = 1.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Add (2 + 3i) + (4 − i).', '6 + 2i.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Multiply (2 + 3i)(1 − i).', '2 − 2i + 3i − 3i² = 5 + i.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is z z* for z = a + bi?', 'a² + b², which is always real and non-negative.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'How do you divide complex numbers?', 'Multiply the numerator and denominator by the conjugate of the denominator.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Calculate (3 + i)/(1 − i).', '(3 + i)(1 + i)/2 = (3 + 4i + i²)/2 = (2 + 4i)/2 = 1 + 2i.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Solve z² + 4 = 0.', 'z = ±2i.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Solve z² − 2z + 5 = 0.', 'z = (2 ± √(4 − 20))/2 = 1 ± 2i.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is an Argand diagram?', 'A diagram representing complex numbers as points, with the real part on the horizontal axis and the imaginary part on the vertical axis.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'How is z* shown on an Argand diagram?', 'As the reflection of z in the real axis.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What does |z − a| represent?', 'The distance from z to the point a on the Argand diagram.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Describe the locus |z − 2 − i| = 3.', 'A circle with centre (2, 1) and radius 3.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Describe the locus |z − 1| = |z + i|.', 'The perpendicular bisector of the points 1 and −i.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Describe the locus arg(z − 1) = π/4.', 'A half-line from (1, 0) at angle π/4 to the positive real axis, not including the point 1.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What does |z| < 2 represent?', 'The interior of a circle centred at the origin with radius 2.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Describe the region |z − 3| ≤ |z + 1|.', 'The points closer to 3 than to −1: Re(z) ≥ 1.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What does arg z = θ represent?', 'A half-line from the origin at angle θ.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is Euler''s formula?', 'e^(iθ) = cos θ + i sin θ.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is the exponential form of a complex number?', 'z = re^(iθ).', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is e^(iπ)?', '−1.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'State de Moivre''s theorem.', '[r(cos θ + i sin θ)]ⁿ = rⁿ(cos nθ + i sin nθ).', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Calculate (1 + i)⁸ using de Moivre.', '(√2)⁸(cos 2π + i sin 2π) = 16.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'How can de Moivre express cos 3θ in terms of cos θ?', 'Expand (cos θ + i sin θ)³ and take the real part: cos 3θ = 4cos³θ − 3cos θ.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'Express sin 3θ in terms of sin θ.', 'sin 3θ = 3 sin θ − 4 sin³θ.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is z + 1/z if z = e^(iθ)?', '2 cos θ.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.2', 'Complex Numbers', 'What is z − 1/z if z = e^(iθ)?', '2i sin θ.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the order of a matrix?', 'The number of rows × the number of columns.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'When can two matrices be multiplied?', 'When the number of columns in the first equals the number of rows in the second.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'Is matrix multiplication commutative?', 'No; in general AB ≠ BA.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'Is matrix multiplication associative?', 'Yes: (AB)C = A(BC).', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the identity matrix I?', 'A square matrix with 1s on the leading diagonal and 0s elsewhere; AI = IA = A.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the determinant of a 2×2 matrix (a b; c d)?', 'ad − bc.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the inverse of a 2×2 matrix (a b; c d)?', '(1/(ad − bc)) × (d −b; −c a).', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is a singular matrix?', 'A matrix with determinant zero, which has no inverse.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is (AB)⁻¹?', 'B⁻¹A⁻¹.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How do you find the determinant of a 3×3 matrix?', 'Expand along a row or column using cofactors: a(ei − fh) − b(di − fg) + c(dh − eg).', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What does the determinant of a transformation matrix represent?', 'The area (2D) or volume (3D) scale factor; a negative value means orientation is reversed.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How can matrices solve simultaneous equations?', 'Write as AX = B, then X = A⁻¹B if A is non-singular.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What does det A = 0 mean for a system of 3 equations?', 'There is no unique solution: either no solutions (inconsistent) or infinitely many.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How do three planes with no unique solution appear geometrically?', 'As a sheaf (common line), a prism (no common point), or with parallel planes.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is det(AB)?', 'det A × det B.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the transpose of a matrix?', 'The matrix formed by swapping rows and columns, Aᵀ.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How do you find the inverse of a 3×3 matrix?', 'Find the matrix of cofactors, transpose it (adjugate), then divide by the determinant.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the zero matrix?', 'A matrix in which every element is 0.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What transformation does (1 0; 0 −1) represent?', 'A reflection in the x-axis.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What transformation does (−1 0; 0 1) represent?', 'A reflection in the y-axis.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What transformation does (0 1; 1 0) represent?', 'A reflection in the line y = x.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What matrix represents an anticlockwise rotation by θ about the origin?', '(cos θ −sin θ; sin θ cos θ).', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What matrix represents an enlargement by scale factor k about the origin?', '(k 0; 0 k).', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What matrix represents a stretch parallel to the x-axis, scale factor k?', '(k 0; 0 1).', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What does the matrix (1 k; 0 1) represent?', 'A shear with the x-axis invariant: each point moves parallel to the x-axis by k times its y-coordinate.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How do you find the image of a point under a transformation?', 'Multiply the transformation matrix by the position vector of the point.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'How do you find the matrix of a transformation?', 'Find the images of the unit vectors i and j (and k); these form the columns.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is the matrix for a combined transformation "A then B"?', 'BA (the first transformation is on the right).', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is an invariant point?', 'A point that maps to itself under a transformation.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.3', 'Matrices', 'What is an invariant line?', 'A line where every point on it maps to a point on the same line.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the vector equation of a line?', 'r = a + λb, where a is a point on the line and b is the direction vector.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the Cartesian equation of a line?', '(x − a₁)/b₁ = (y − a₂)/b₂ = (z − a₃)/b₃.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the scalar (dot) product?', 'a·b = a₁b₁ + a₂b₂ + a₃b₃ = |a||b| cos θ.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What does a·b = 0 mean?', 'The vectors are perpendicular.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the angle between two lines?', 'Use the dot product of their direction vectors: cos θ = (b₁·b₂)/(|b₁||b₂|).', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the vector equation of a plane?', 'r = a + λb + μc, or r·n = a·n.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the Cartesian equation of a plane?', 'n₁x + n₂y + n₃z = d, where n is the normal.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is a normal vector to a plane?', 'A vector perpendicular to the plane.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the angle between a line and a plane?', 'Find the angle between the direction and the normal, then subtract from 90°.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the angle between two planes?', 'Find the angle between their normals.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find where a line meets a plane?', 'Substitute the line''s parametric form into the plane equation and solve for λ.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you tell if two lines are skew?', 'They are not parallel and don''t intersect.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the intersection of two lines?', 'Set the vector equations equal and solve for the parameters, checking all three components.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the vector (cross) product?', 'a × b, a vector perpendicular to both a and b with magnitude |a||b| sin θ.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you calculate a × b?', '(a₂b₃ − a₃b₂, a₃b₁ − a₁b₃, a₁b₂ − a₂b₁).', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the normal to a plane containing vectors b and c?', 'Calculate b × c.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the perpendicular distance from a point to a plane?', '|ax₀ + by₀ + cz₀ − d|/√(a² + b² + c²).', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the shortest distance between skew lines?', '|(a₂ − a₁)·n|/|n|, where n = b₁ × b₂.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the shortest distance from a point to a line?', 'Find the foot of the perpendicular (where (p − r)·b = 0), then find the distance.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the area of a triangle using vectors?', '½|AB × AC|.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the volume of a parallelepiped?', '|a·(b × c)| (the scalar triple product).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the line of intersection of two planes?', 'It has direction n₁ × n₂; find a point by solving the equations with one variable fixed.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you find the reflection of a point in a plane?', 'Find the foot of the perpendicular, then go the same distance beyond it.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'When are two planes parallel?', 'When their normals are parallel.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What does r·n = d mean geometrically?', 'All points whose component along n is d/|n| from the origin.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'Find the angle between (1, 2, 2) and (2, −1, 2).', 'Dot product = 2 − 2 + 4 = 4; |a| = |b| = 3; cos θ = 4/9, θ ≈ 63.6°.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'How do you check a point lies on a line?', 'Find a λ that satisfies all three components.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is a unit normal?', 'A normal vector divided by its magnitude.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'Find the Cartesian equation of the plane with normal (2, −1, 3) through (1, 1, 1).', '2x − y + 3z = 4.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.4', 'Vectors', 'What is the scalar product of a vector with itself?', 'a·a = |a|².', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is Σ r from r = 1 to n?', 'n(n + 1)/2.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is Σ r² from r = 1 to n?', 'n(n + 1)(2n + 1)/6.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is Σ r³ from r = 1 to n?', 'n²(n + 1)²/4.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is Σ 1 from r = 1 to n?', 'n.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Evaluate Σ r² from r = 1 to 10.', '10 × 11 × 21/6 = 385.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find Σ (2r − 1) from r = 1 to n.', 'n(n + 1) − n = n².', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find Σ r(r + 1) from r = 1 to n.', 'Σr² + Σr = n(n + 1)(n + 2)/3.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'How do you evaluate Σ from r = 11 to 20?', 'Σ from 1 to 20 minus Σ from 1 to 10.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the method of differences?', 'Writing each term as f(r) − f(r + 1) so that most terms cancel when summed.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Use the method of differences to sum Σ 1/(r(r + 1)).', '1/(r(r + 1)) = 1/r − 1/(r + 1), so the sum from 1 to n is 1 − 1/(n + 1).', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find Σ 1/(r(r + 2)) from r = 1 to n.', '½ Σ (1/r − 1/(r + 2)) = ½(3/2 − 1/(n + 1) − 1/(n + 2)).', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is a telescoping series?', 'A series in which consecutive terms cancel, leaving only a few terms.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the sum to infinity of Σ 1/(r(r + 1))?', '1.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'How do you prove a summation formula?', 'Using the standard results, the method of differences, or proof by induction.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is Σ (ar + b)?', 'aΣr + bn.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is a Maclaurin series?', 'f(x) = f(0) + f''(0)x + f''''(0)x²/2! + f''''''(0)x³/3! + …', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the Maclaurin series for eˣ?', '1 + x + x²/2! + x³/3! + …, valid for all x.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the Maclaurin series for sin x?', 'x − x³/3! + x⁵/5! − …, valid for all x.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the Maclaurin series for cos x?', '1 − x²/2! + x⁴/4! − …, valid for all x.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the Maclaurin series for ln(1 + x)?', 'x − x²/2 + x³/3 − …, valid for −1 < x ≤ 1.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the Maclaurin series for (1 + x)ⁿ?', '1 + nx + n(n − 1)x²/2! + …, valid for |x| < 1 (non-integer n).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find the Maclaurin series for e^(2x) up to x³.', '1 + 2x + 2x² + (4/3)x³.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find the series for sin 3x up to x³.', '3x − (27/6)x³ = 3x − 4.5x³.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find the series for eˣ sin x up to x³.', '(1 + x + x²/2)(x − x³/6) = x + x² + x³/3 + …', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find the series for ln(1 − x) up to x³.', '−x − x²/2 − x³/3.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'What is the validity of ln(1 − x)''s series?', '−1 ≤ x < 1.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'How can a Maclaurin series approximate a value?', 'Substitute a small x into the first few terms, e.g. e^0.1 ≈ 1 + 0.1 + 0.005.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'How can series find limits?', 'Replace functions with their series and simplify, e.g. lim (sin x)/x = 1.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find lim (x→0) of (1 − cos x)/x².', '(x²/2 − …)/x² → 1/2.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.5', 'Series', 'Find lim (x→0) of (eˣ − 1)/x.', '(x + x²/2 + …)/x → 1.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'For ax² + bx + c = 0 with roots α, β, what are α + β and αβ?', 'α + β = −b/a and αβ = c/a.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'For ax³ + bx² + cx + d = 0, what are Σα, Σαβ and αβγ?', 'Σα = −b/a, Σαβ = c/a, αβγ = −d/a.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'For a quartic ax⁴ + bx³ + cx² + dx + e = 0, what is the product of the roots?', 'αβγδ = e/a.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Express α² + β² in terms of α + β and αβ.', '(α + β)² − 2αβ.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Express α³ + β³ in terms of α + β and αβ.', '(α + β)³ − 3αβ(α + β).', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Express 1/α + 1/β in terms of α + β and αβ.', '(α + β)/αβ.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Express α² + β² + γ² for a cubic.', '(Σα)² − 2Σαβ.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How do you find an equation whose roots are 2α and 2β?', 'Substitute x = w/2 into the original equation.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How do you find an equation whose roots are α + 1, β + 1?', 'Substitute x = w − 1 into the original equation.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How do you find an equation with roots α², β² using substitution?', 'Substitute x = √w, rearrange so √w terms are on one side, and square.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'The roots of x² − 5x + 3 = 0 are α, β. Find α² + β².', '25 − 6 = 19.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'The roots of 2x³ − 3x² + x − 4 = 0 are α, β, γ. Find αβγ.', '−(−4)/2 = 2.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Find the quadratic with roots α + β and αβ given α + β = 3, αβ = 2.', 'Roots 3 and 2: x² − 5x + 6 = 0.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'If one root of x³ − 6x² + 11x − 6 = 0 is 1, find the others.', '(x − 1)(x² − 5x + 6), so 2 and 3.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What does it mean if a cubic''s roots form an arithmetic sequence?', 'They can be written a − d, a, a + d, and Σα = 3a.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Why do real polynomials have complex roots in conjugate pairs?', 'Taking the conjugate of p(z) = 0 gives p(z*) = 0, because the coefficients are real.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'A real cubic has roots 2 and 1 + i. Find the cubic.', 'Roots 2, 1 ± i: (x − 2)(x² − 2x + 2) = x³ − 4x² + 6x − 4.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How many real roots can a real cubic have?', 'One or three (counting repeated roots).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How many complex (non-real) roots can a real quartic have?', '0, 2 or 4.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What is Σα for x⁴ − 2x³ + x − 7 = 0?', '2.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What is Σαβγ for a quartic ax⁴ + bx³ + cx² + dx + e?', '−d/a.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Find α³ + β³ if α + β = 2 and αβ = −1.', '8 − 3(−1)(2) = 14.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How do you find 1/α + 1/β + 1/γ for a cubic?', 'Σαβ/αβγ.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What does a repeated root mean for the graph?', 'The graph touches the x-axis at that point.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'If x = 2 + 3i is a root of a real polynomial, what else must be?', '2 − 3i.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How can the sum and product of roots check a solution?', 'Compare the computed roots'' sum and product with −b/a and c/a.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What substitution gives roots 1/α, 1/β, 1/γ?', 'Substitute x = 1/w (this reverses the coefficients).', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'Find the equation with roots 1/α, 1/β if α, β are roots of 2x² + 3x − 1 = 0.', 'Reverse the coefficients: −w² + 3w + 2 = 0, i.e. w² − 3w − 2 = 0.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'How many roots does a polynomial of degree n have?', 'Exactly n roots in the complex numbers, counting multiplicity.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.6', 'Roots of Polynomials', 'What is the Fundamental Theorem of Algebra?', 'Every non-constant polynomial has at least one complex root.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What are polar coordinates?', 'Coordinates (r, θ), where r is the distance from the pole and θ is the angle from the initial line.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you convert polar to Cartesian?', 'x = r cos θ, y = r sin θ.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you convert Cartesian to polar?', 'r² = x² + y², tan θ = y/x (taking care with the quadrant).', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the polar equation r = a?', 'A circle with centre the pole and radius a.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the polar equation θ = α?', 'A half-line from the pole at angle α.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = aθ?', 'A spiral (Archimedean spiral).', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = a(1 + cos θ)?', 'A cardioid.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = a cos 2θ?', 'A four-petalled rose curve.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the curve r = 2a cos θ?', 'A circle through the pole, with centre (a, 0) and radius a.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the area enclosed by a polar curve?', 'A = ½ ∫ r² dθ between the limits.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Find the area enclosed by r = 2 for 0 ≤ θ ≤ 2π.', '½ ∫ 4 dθ = 4π.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Find the area of the cardioid r = 1 + cos θ.', '½ ∫₀^(2π) (1 + cos θ)² dθ = 3π/2.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you find where two polar curves intersect?', 'Set the r-values equal and solve for θ, also checking the pole.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you find a tangent parallel to the initial line?', 'Set dy/dθ = 0, where y = r sin θ.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you find a tangent perpendicular to the initial line?', 'Set dx/dθ = 0, where x = r cos θ.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Convert r = 4 sin θ to Cartesian form.', 'r² = 4r sin θ, so x² + y² = 4y (a circle centred at (0, 2)).', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Convert x² + y² = 9 to polar form.', 'r = 3.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Convert y = x to polar form.', 'θ = π/4 (and θ = −3π/4 for negative r).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Why is r usually taken as non-negative?', 'By convention r ≥ 0; values of θ that give negative r are excluded from the sketch.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What does a cardioid look like?', 'A heart shape with a cusp at the pole.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How many petals does r = cos 3θ have?', '3.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How many petals does r = cos 2θ have?', '4.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the area of one petal of r = cos 2θ?', '½ ∫ from −π/4 to π/4 of cos²2θ dθ = π/8.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What identity helps integrate r² = cos²θ?', 'cos²θ = (1 + cos 2θ)/2.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you sketch a polar curve?', 'Tabulate r for key θ values, note symmetry, and find where r = 0 and r is maximum.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What does symmetry about the initial line mean for r = f(θ)?', 'f(−θ) = f(θ), e.g. curves involving only cos θ.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'How do you find the area between two polar curves?', 'Subtract the areas: ½ ∫ (r₁² − r₂²) dθ over the appropriate range.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the maximum r of r = 3 + 2 cos θ?', '5, when θ = 0.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'Does r = 3 + 2 cos θ pass through the pole?', 'No, since r ≥ 1 for all θ (a dimpled limaçon).', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.7', 'Polar Coordinates', 'What is the pole?', 'The origin in polar coordinates.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of sinh x?', 'sinh x = (eˣ − e^(−x))/2.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of cosh x?', 'cosh x = (eˣ + e^(−x))/2.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the definition of tanh x?', 'tanh x = sinh x/cosh x = (eˣ − e^(−x))/(eˣ + e^(−x)).', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the key hyperbolic identity?', 'cosh²x − sinh²x = 1.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the range of cosh x?', 'cosh x ≥ 1.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the range of tanh x?', '−1 < tanh x < 1.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What does the graph of y = cosh x look like?', 'A U-shape (catenary) with minimum (0, 1), symmetric about the y-axis.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What does the graph of y = sinh x look like?', 'An S-shape through the origin, increasing, and odd.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of sinh x?', 'cosh x.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of cosh x?', 'sinh x.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of tanh x?', 'sech²x.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is Osborn''s rule?', 'To convert a trig identity to a hyperbolic one, replace cos with cosh and sin with sinh, but change the sign of any product of two sines.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is sinh 2x?', '2 sinh x cosh x.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is cosh 2x?', 'cosh²x + sinh²x = 2cosh²x − 1 = 1 + 2sinh²x.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is arsinh x in logarithmic form?', 'ln(x + √(x² + 1)).', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is arcosh x in logarithmic form?', 'ln(x + √(x² − 1)), for x ≥ 1.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is artanh x in logarithmic form?', '½ ln((1 + x)/(1 − x)), for |x| < 1.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of arsinh x?', '1/√(x² + 1).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of arcosh x?', '1/√(x² − 1).', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is the derivative of artanh x?', '1/(1 − x²).', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve cosh x = 2.', 'x = ±ln(2 + √3).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve sinh x = 3/4.', 'x = ln(3/4 + 5/4) = ln 2.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'Solve 3 sinh x + cosh x = 3.', 'In exponentials: 3(eˣ − e^(−x))/2 + (eˣ + e^(−x))/2 = 3 → 2eˣ − e^(−x) = 3 → 2e^(2x) − 3eˣ − 1 = 0, eˣ = (3 + √17)/4, x = ln((3 + √17)/4).', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ sinh x dx?', 'cosh x + c.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ cosh x dx?', 'sinh x + c.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is ∫ tanh x dx?', 'ln cosh x + c.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is a catenary?', 'The shape of a hanging chain, described by y = a cosh(x/a).', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'Is cosh x even or odd?', 'Even.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'Is sinh x even or odd?', 'Odd.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.8', 'Hyperbolic Functions', 'What is sech x?', '1/cosh x.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is an improper integral?', 'An integral where a limit is infinite or the integrand is undefined at a point in the range.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How do you evaluate ∫₁^∞ 1/x² dx?', 'lim (t→∞) [−1/x]₁ᵗ = 1.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Does ∫₁^∞ 1/x dx converge?', 'No; ln t → ∞, so it diverges.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Evaluate ∫₀¹ 1/√x dx.', '[2√x]₀¹ = 2 (the integral converges even though 1/√x is undefined at 0).', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the mean value of f(x) over [a, b]?', '(1/(b − a)) ∫ₐᵇ f(x) dx.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Find the mean value of x² over [0, 3].', '(1/3) × 9 = 3.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is ∫ 1/√(1 − x²) dx?', 'arcsin x + c.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is ∫ 1/(1 + x²) dx?', 'arctan x + c.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is ∫ 1/√(a² − x²) dx?', 'arcsin(x/a) + c.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is ∫ 1/(a² + x²) dx?', '(1/a) arctan(x/a) + c.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the derivative of arcsin x?', '1/√(1 − x²).', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the derivative of arccos x?', '−1/√(1 − x²).', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the derivative of arctan x?', '1/(1 + x²).', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Integrate 1/(x² + 4).', '(1/2) arctan(x/2) + c.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Integrate 1/√(9 − x²).', 'arcsin(x/3) + c.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How do you integrate 1/(x² + 2x + 5)?', 'Complete the square: (x + 1)² + 4, giving (1/2) arctan((x + 1)/2) + c.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How do partial fractions help integrate 1/((x + 1)(x² + 1))?', 'Split into A/(x + 1) + (Bx + C)/(x² + 1), then integrate using ln and arctan.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the partial fraction form for (px + q)/((x − a)(x² + b²))?', 'A/(x − a) + (Bx + C)/(x² + b²).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the volume of revolution about the x-axis?', 'V = π ∫ y² dx between the limits.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the volume of revolution about the y-axis?', 'V = π ∫ x² dy between the y-limits.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Find the volume when y = x from 0 to 3 is rotated about the x-axis.', 'π ∫₀³ x² dx = 9π (a cone).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Find the volume when y = √x from 0 to 4 is rotated about the x-axis.', 'π ∫₀⁴ x dx = 8π.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Find the volume when y = x² from 0 to 1 is rotated about the x-axis.', 'π ∫₀¹ x⁴ dx = π/5.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How do you find the volume between two curves rotated about the x-axis?', 'V = π ∫ (y₁² − y₂²) dx, where y₁ is the outer curve.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'Why is it not π ∫ (y₁ − y₂)² dx?', 'The solid is a washer: the volume is the outer solid minus the inner solid.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How do you rotate y = x² about the y-axis between y = 0 and y = 4?', 'x² = y, so V = π ∫₀⁴ y dy = 8π.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the volume of a sphere derived by rotation?', 'Rotate x² + y² = r² about the x-axis: π ∫₋ᵣʳ (r² − x²) dx = (4/3)πr³.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What is the volume of a cone derived by rotation?', 'Rotate y = (r/h)x from 0 to h: π ∫ (r²/h²)x² dx = (1/3)πr²h.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'How can volumes of revolution model real objects?', 'E.g. vases, bottles and bowls can be modelled by rotating curves.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.9', 'Further Calculus', 'What assumption is made when modelling an object with a volume of revolution?', 'The object is perfectly symmetrical about its axis and the curve accurately describes its profile.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is an integrating factor?', 'For dy/dx + P(x)y = Q(x), the integrating factor is e^(∫P dx).', 1),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'How do you solve dy/dx + P(x)y = Q(x)?', 'Multiply by the integrating factor I: d(Iy)/dx = IQ, then integrate.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'Solve dy/dx + 2y = e^(−x).', 'IF = e^(2x): (ye^(2x))'' = eˣ, so y = e^(−x) + Ce^(−2x).', 3),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'Solve x dy/dx + y = x².', '(xy)'' = x², so xy = x³/3 + C, y = x²/3 + C/x.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is a second-order linear differential equation with constant coefficients?', 'a d²y/dx² + b dy/dx + cy = f(x).', 5),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the auxiliary equation?', 'am² + bm + c = 0.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the complementary function if the auxiliary equation has distinct real roots α, β?', 'y = Ae^(αx) + Be^(βx).', 7),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the complementary function for a repeated root α?', 'y = (A + Bx)e^(αx).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the complementary function for complex roots p ± qi?', 'y = e^(px)(A cos qx + B sin qx).', 9),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the general solution of a non-homogeneous second-order ODE?', 'Complementary function + particular integral.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is a particular integral?', 'Any solution of the full equation, found by trying a function similar to f(x).', 11),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What trial function is used for f(x) = ke^(λx)?', 'Ae^(λx) (or Axe^(λx) if λ is a root of the auxiliary equation).', 12),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What trial function is used for f(x) = polynomial of degree n?', 'A general polynomial of degree n.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What trial function is used for f(x) = k cos ωx?', 'A cos ωx + B sin ωx.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What happens if the trial function is part of the complementary function?', 'Multiply the trial by x (or x² for a repeated root).', 15),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'Solve y'''' − 5y'' + 6y = 0.', 'm² − 5m + 6 = 0, m = 2, 3: y = Ae^(2x) + Be^(3x).', 16),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'Solve y'''' + 4y = 0.', 'm = ±2i: y = A cos 2x + B sin 2x.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'Solve y'''' + 2y'' + y = 0.', 'm = −1 (repeated): y = (A + Bx)e^(−x).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is simple harmonic motion as a differential equation?', 'd²x/dt² = −ω²x.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the general solution of d²x/dt² = −ω²x?', 'x = A cos ωt + B sin ωt.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is damped harmonic motion?', 'd²x/dt² + k dx/dt + ω²x = 0, where the damping term reduces the amplitude.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is heavy damping?', 'The auxiliary equation has two distinct real (negative) roots; the system returns to equilibrium slowly without oscillating.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is critical damping?', 'The auxiliary equation has a repeated root; the system returns to equilibrium fastest without oscillating.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is light damping?', 'The auxiliary equation has complex roots; the system oscillates with decreasing amplitude.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is forced oscillation?', 'An oscillating system with an external driving force: x'''' + kx'' + ω²x = f(t).', 25),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is resonance in DEs?', 'When the driving frequency equals the natural frequency, amplitude grows (the particular integral includes t).', 26),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'How is population growth with limits modelled?', 'dP/dt = kP(1 − P/K), the logistic equation.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'How is predator–prey interaction modelled?', 'Using coupled first-order differential equations for each population.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What is the general strategy for coupled DEs?', 'Eliminate one variable by differentiating to give a second-order DE in the other.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', '1.10', 'Differential Equations', 'What does the steady state of a model mean?', 'The long-term behaviour, e.g. when derivatives are zero.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a graph in decision maths?', 'A set of vertices (nodes) connected by edges (arcs).', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is the degree (order) of a vertex?', 'The number of edges meeting at that vertex (a loop counts twice).', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is the handshaking lemma?', 'The sum of the degrees of all vertices is twice the number of edges, so there is an even number of odd vertices.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a simple graph?', 'A graph with no loops and no multiple edges between the same pair of vertices.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a connected graph?', 'A graph where there is a path between every pair of vertices.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a complete graph Kₙ?', 'A simple graph where every vertex is joined to every other vertex.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'How many edges does Kₙ have?', 'n(n − 1)/2.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a bipartite graph?', 'A graph whose vertices split into two sets, with edges only joining vertices in different sets.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is K₃,₃?', 'The complete bipartite graph with two sets of three vertices, each joined to all three in the other set.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a tree?', 'A connected graph with no cycles.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'How many edges does a tree with n vertices have?', 'n − 1.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a spanning tree?', 'A tree that includes every vertex of a graph.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a walk?', 'A sequence of edges where the end of one is the start of the next.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a trail?', 'A walk with no repeated edges.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a path?', 'A walk with no repeated vertices.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a cycle?', 'A closed path, returning to the start with no other repeated vertices.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is an Eulerian graph?', 'A graph with a closed trail using every edge exactly once; all vertices have even degree.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a semi-Eulerian graph?', 'A graph with exactly two odd vertices, which has a trail using every edge once, starting and ending at the odd vertices.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a Hamiltonian cycle?', 'A cycle that visits every vertex exactly once.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a planar graph?', 'A graph that can be drawn with no edges crossing.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is Euler''s formula for planar graphs?', 'V − E + F = 2 (for a connected planar graph).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is the planarity algorithm?', 'A method using a Hamiltonian cycle to test whether a graph is planar, by placing edges inside or outside.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is Kuratowski''s theorem?', 'A graph is planar if and only if it contains no subdivision of K₅ or K₃,₃.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'Are K₅ and K₃,₃ planar?', 'No.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is an isomorphism between graphs?', 'A one-to-one correspondence between vertices that preserves edges.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a digraph?', 'A directed graph, where edges have directions.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is an adjacency matrix?', 'A matrix showing the number of edges between each pair of vertices.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a distance matrix?', 'A matrix showing the weights of edges between vertices.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is the complement of a simple graph G?', 'The graph with the same vertices, where edges exist exactly where they don''t in G.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.1', 'Graphs & Networks', 'What is a subgraph?', 'A graph formed from a subset of the vertices and edges of another graph.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is a minimum spanning tree?', 'A spanning tree with the smallest total edge weight.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'Describe Kruskal''s algorithm.', 'Sort edges by weight; add the shortest edge that doesn''t form a cycle, until all vertices are connected.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'Describe Prim''s algorithm.', 'Start at any vertex; repeatedly add the shortest edge joining a vertex in the tree to one not in the tree.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'Why is Prim''s algorithm suited to distance matrices?', 'It works column by column, choosing the smallest entry in the rows of vertices already in the tree.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the key difference between Prim''s and Kruskal''s?', 'Kruskal''s builds a forest that joins up; Prim''s grows a single tree.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'Describe Dijkstra''s algorithm.', 'Label the start 0; repeatedly give a permanent label to the vertex with the smallest temporary label, updating neighbours'' temporary labels.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What does Dijkstra''s algorithm find?', 'The shortest path from a start vertex to all other vertices.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How do you trace back the shortest route in Dijkstra''s?', 'Work backwards from the end, choosing edges where the weight equals the difference in permanent labels.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is Floyd''s algorithm?', 'An algorithm finding the shortest paths between all pairs of vertices using distance and route matrices.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the route inspection (Chinese postman) problem?', 'Finding the shortest route that travels every edge at least once and returns to the start.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How do you solve the route inspection problem?', 'Find the odd vertices, pair them to minimise the extra distance, add those paths, then total = sum of edges + extra.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How many pairings are there for 4 odd vertices?', '3.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How many pairings are there for 6 odd vertices?', '15.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What if the route can start and end at different vertices?', 'Leave the pair of odd vertices with the longest connecting path unrepeated, starting and ending there.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the travelling salesperson problem (TSP)?', 'Finding the shortest route visiting every vertex and returning to the start.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the classical TSP versus the practical TSP?', 'Classical: each vertex visited exactly once. Practical: vertices can be revisited.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How do you find an upper bound for the TSP?', 'Use the nearest neighbour algorithm, or double the minimum spanning tree and use shortcuts.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the nearest neighbour algorithm?', 'From the current vertex, go to the nearest unvisited vertex; return to the start at the end.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'How do you find a lower bound for the TSP?', 'Delete a vertex, find the MST of the rest, then add the two shortest edges from the deleted vertex.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the best upper bound?', 'The smallest upper bound found.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the best lower bound?', 'The largest lower bound found.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What does it mean if the upper and lower bounds are equal?', 'The optimal solution has been found.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is a network flow?', 'The movement of a quantity through a network with capacities on the arcs.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is a cut in a network?', 'A set of arcs whose removal separates the source from the sink.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the max-flow min-cut theorem?', 'The maximum flow through a network equals the capacity of the minimum cut.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the feasibility condition for flows?', 'Flow in each arc doesn''t exceed capacity, and flow into each vertex equals flow out (except source and sink).', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is a supersource?', 'An extra vertex added to connect multiple sources into one.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the complexity of Kruskal''s algorithm?', 'Dominated by sorting the edges: O(E log E).', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is the complexity of Dijkstra''s algorithm (simple version)?', 'O(n²) for n vertices.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.2', 'Network Algorithms', 'What is an algorithm''s order?', 'How the run time grows with problem size, e.g. quadratic O(n²).', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is linear programming?', 'Optimising a linear objective function subject to linear constraints.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What are decision variables?', 'The variables whose values are chosen, e.g. x = number of chairs, y = number of tables.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the objective function?', 'The expression to be maximised or minimised, e.g. P = 3x + 5y.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What are constraints?', 'Linear inequalities that limit the values of the decision variables.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What are non-negativity constraints?', 'x ≥ 0, y ≥ 0.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the feasible region?', 'The region of the graph satisfying all the constraints.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How is the optimal solution found graphically?', 'Use an objective line (ruler method) or test each vertex of the feasible region.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the ruler (objective line) method?', 'Slide a line of the objective function across the feasible region; the last point it touches is optimal.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'Why does the optimum occur at a vertex?', 'The objective function is linear, so its maximum or minimum over a convex polygon is at a vertex.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What if integer solutions are required?', 'Test integer points near the optimal vertex within the feasible region.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the simplex algorithm?', 'An algebraic method that moves between vertices of the feasible region, improving the objective each step.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is a slack variable?', 'A variable added to a ≤ constraint to make it an equation, e.g. x + y + s = 10.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is a surplus variable?', 'A variable subtracted from a ≥ constraint to make it an equation.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How do you choose the pivot column in simplex?', 'The column with the most negative value in the objective row (for maximisation).', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How do you choose the pivot row?', 'The row with the smallest non-negative ratio of the value to the pivot column entry.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'When is the simplex tableau optimal?', 'When there are no negative values in the objective row (for maximisation).', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the two-stage simplex method?', 'A method for problems with ≥ constraints, first minimising artificial variables to find a feasible solution.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is the Big-M method?', 'Adding artificial variables with a large penalty M in the objective to handle ≥ constraints.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is an artificial variable?', 'A variable added to ≥ or = constraints to give an initial basic feasible solution.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How do you convert a minimisation problem for simplex?', 'Maximise the negative of the objective function.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is a basic variable?', 'A variable that is non-zero in the current solution (in the basis).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is a non-basic variable?', 'A variable set to zero in the current solution.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What does a slack variable''s final value represent?', 'The unused amount of that resource.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'Formulate: each chair uses 2 h and each table 3 h, with 60 h available.', '2x + 3y ≤ 60.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is an unbounded LP problem?', 'One where the objective can increase without limit because the feasible region is unbounded.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What does an infeasible LP problem mean?', 'No point satisfies all the constraints.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How do you find the vertices of a feasible region?', 'Solve pairs of boundary equations simultaneously.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is sensitivity analysis?', 'Examining how changes in coefficients or constraints affect the optimal solution.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'What is a degenerate solution in simplex?', 'When a basic variable has value zero, which can cause cycling.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.3', 'Linear Programming', 'How do you interpret the final simplex tableau?', 'Read the basic variables'' values from the value column; the objective row gives the optimal value.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is critical path analysis?', 'A method for scheduling project activities to find the minimum project duration.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is an activity network?', 'A diagram showing activities and their dependencies (precedences).', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is activity-on-arc?', 'A network where activities are represented by arcs, and events by nodes.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is activity-on-node?', 'A network where activities are represented by nodes.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is a dummy activity?', 'An activity of zero duration used to show dependencies correctly or maintain unique numbering.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is a precedence table?', 'A table listing each activity, its duration and the activities that must finish before it starts.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the earliest event time?', 'The earliest time an event can occur, found by a forward pass.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the latest event time?', 'The latest time an event can occur without delaying the project, found by a backward pass.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'How is the forward pass carried out?', 'Take the maximum of (earliest event time + activity duration) over all activities entering a node.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'How is the backward pass carried out?', 'Take the minimum of (latest event time − activity duration) over all activities leaving a node.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the total float of an activity?', 'Latest finish time − earliest start time − duration.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is a critical activity?', 'An activity with zero total float.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the critical path?', 'The longest path through the network, consisting of critical activities.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the minimum project duration?', 'The length of the critical path.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is independent float?', 'The amount an activity can be delayed without affecting any other activity.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is a Gantt (cascade) chart?', 'A chart showing activities as bars against time, with float shown.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is resource histogram?', 'A chart showing the number of workers needed at each time.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is resource levelling?', 'Rescheduling activities within their floats to reduce the peak number of workers.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the lower bound for the number of workers?', 'Total activity time ÷ critical path length, rounded up.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is scheduling?', 'Assigning activities to workers so the project is completed as efficiently as possible.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What happens if a critical activity is delayed?', 'The whole project is delayed.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What happens if a non-critical activity is delayed by less than its float?', 'The project isn''t delayed.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'How do you identify critical events?', 'Events where the earliest and latest event times are equal.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is crashing a network?', 'Reducing activity durations (often at extra cost) to shorten the project.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'Why might there be more than one critical path?', 'Several paths may have the same maximum length.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the purpose of a dummy in activity-on-arc when two activities share start and end events?', 'To keep each activity uniquely identified by its start and end events.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'How do you read precedences from an activity network?', 'An activity can start only when all activities entering its start node are finished.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the latest start time of an activity?', 'The latest event time at its end minus its duration.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'What is the earliest finish time of an activity?', 'The earliest event time at its start plus its duration.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.4', 'Critical Path Analysis', 'Why is CPA useful?', 'It helps plan projects, allocate resources, and identify which activities need close monitoring.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is simulation?', 'Modelling a real situation using random numbers to explore its behaviour.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'Why use simulation?', 'When a system is too complex, costly or dangerous to study directly or solve analytically.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What are random numbers used for in simulation?', 'To model random events according to given probabilities.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How do you allocate random numbers to outcomes?', 'Assign ranges of random numbers in proportion to each outcome''s probability.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'Allocate two-digit random numbers for outcomes with probabilities 0.3, 0.5 and 0.2.', '00–29, 30–79 and 80–99.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a pseudo-random number?', 'A number generated by an algorithm that appears random but is determined by a starting seed.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'Why must rejected random numbers sometimes be used?', 'When the range doesn''t divide evenly, some numbers are discarded to keep probabilities correct.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a queue simulation?', 'Simulating customer arrivals and service times to study waiting times.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is inter-arrival time?', 'The time between successive arrivals.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is service time?', 'The time taken to serve a customer.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What measures can a queue simulation produce?', 'Average waiting time, queue length, and server idle time.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can simulation reliability be improved?', 'Run more trials and average the results.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a spreadsheet''s role in simulation?', 'It can generate random numbers and run many repetitions quickly.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a limitation of simulation?', 'It gives estimates, not exact answers, and depends on the accuracy of the model''s assumptions.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can simulation model a continuous distribution?', 'Using random numbers with the inverse cumulative distribution function.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How do you simulate a fair die with random digits 0–9?', 'Use 1–6 as outcomes and reject 0, 7, 8 and 9.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can simulation help decide staffing levels?', 'Simulate queues with different numbers of servers and compare waiting times and costs.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is Monte Carlo simulation?', 'Using repeated random sampling to estimate numerical results.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can simulation estimate π?', 'Generate random points in a square and count the proportion inside the inscribed circle.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a model''s validity in simulation?', 'How well the simulation reflects the real-world situation.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How do you compare simulation results with theory?', 'Compare the average simulated result with the expected value calculated theoretically.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is the seed of a random number generator?', 'The starting value that determines the sequence of pseudo-random numbers.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is a discrete event simulation?', 'Modelling a system as a sequence of events at specific times, e.g. arrivals and departures.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can simulation model inventory control?', 'Simulate daily demand and deliveries to see stock levels and shortages.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is the purpose of a trial run?', 'To check the simulation works correctly before running many repetitions.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How can bias occur in simulation?', 'Incorrect allocation of random numbers or unrepresentative assumptions.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What is sensitivity in a simulation?', 'How much the results change when inputs or assumptions change.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'Why should a simulation be repeated with different random numbers?', 'To check the results are consistent and not due to chance.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'How do you simulate an event with probability 0.35 using three-digit random numbers?', 'Use 000–349 for the event occurring, 350–999 for it not occurring.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'A1.5', 'Simulation', 'What does a simulation''s output depend on?', 'The model, its assumptions, the random numbers used, and the number of runs.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What is dimensional analysis?', 'Checking equations and deriving relationships using the dimensions of quantities: mass (M), length (L) and time (T).', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of velocity?', 'LT⁻¹.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of acceleration?', 'LT⁻².', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of force?', 'MLT⁻².', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of energy?', 'ML²T⁻².', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of power?', 'ML²T⁻³.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of momentum?', 'MLT⁻¹.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of pressure?', 'ML⁻¹T⁻².', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of density?', 'ML⁻³.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of the gravitational constant G?', 'M⁻¹L³T⁻².', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of frequency?', 'T⁻¹.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of an angle?', 'Dimensionless.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What does it mean for an equation to be dimensionally consistent?', 'Each term has the same dimensions.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'Can a dimensionally consistent equation be wrong?', 'Yes; dimensionless constants (e.g. ½ or 2π) can''t be checked.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'Use dimensional analysis to find how the period of a pendulum depends on l, m and g.', 'T = kl^α m^β g^γ: T¹ = L^(α+γ) M^β T^(−2γ), so β = 0, γ = −½, α = ½: T = k√(l/g).', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of work?', 'ML²T⁻² (the same as energy).', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of impulse?', 'MLT⁻¹ (the same as momentum).', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of a spring constant k?', 'MT⁻².', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of the modulus of elasticity λ?', 'MLT⁻² (a force).', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of viscosity if F = ηAv/d?', 'ML⁻¹T⁻¹.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'Why are trigonometric and exponential function arguments dimensionless?', 'These functions only make sense for pure numbers.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What is the SI unit corresponding to M?', 'The kilogram (kg).', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'How do you find dimensions from units?', 'Replace kg with M, m with L and s with T.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'Find the dimensions of ½mv².', 'M(LT⁻¹)² = ML²T⁻², consistent with energy.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'Check the dimensions of v² = u² + 2as.', 'L²T⁻² on both sides, since as has dimensions LT⁻² × L.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of angular velocity?', 'T⁻¹.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of surface tension (force per unit length)?', 'MT⁻².', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'How can dimensional analysis predict the effect of doubling a variable?', 'If Q ∝ xⁿ, doubling x multiplies Q by 2ⁿ.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What is a limitation of dimensional analysis?', 'It can''t find dimensionless constants or distinguish between quantities with the same dimensions.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.1', 'Dimensional Analysis', 'What are the dimensions of torque (moment)?', 'ML²T⁻² (the same as energy, although it isn''t energy).', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is work done by a constant force?', 'W = Fs cos θ, where θ is the angle between the force and displacement.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is kinetic energy?', '½mv².', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is gravitational potential energy?', 'mgh, relative to a chosen level.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the work–energy principle?', 'The work done by the resultant force equals the change in kinetic energy.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the principle of conservation of mechanical energy?', 'If only conservative forces (gravity, elastic) do work, KE + PE is constant.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is elastic potential energy in a string or spring?', 'λx²/(2l), where λ is the modulus of elasticity, x the extension and l the natural length.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is Hooke''s law in terms of λ?', 'T = λx/l.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is power?', 'The rate of doing work: P = W/t.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the power of a force moving at velocity v?', 'P = Fv.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'A car''s engine works at 30 kW at a constant 20 m/s. What is the driving force?', 'F = P/v = 1500 N.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the maximum speed of a vehicle with power P against resistance R?', 'When driving force = resistance: v = P/R.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'How is work done against friction calculated?', 'Work = friction force × distance = μR × d.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'A 2 kg particle falls 5 m from rest. Find its speed (g = 9.8).', '½ × 2 × v² = 2 × 9.8 × 5, so v = √98 ≈ 9.90 m/s.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the unit of power?', 'The watt (W), 1 J/s.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the unit of work?', 'The joule (J), 1 N m.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'How is the work done by a variable force found?', 'W = ∫ F dx.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the work done in stretching a string from extension a to b?', 'λ(b² − a²)/(2l).', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is a conservative force?', 'A force for which the work done is independent of the path taken, e.g. gravity.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is a non-conservative force?', 'A force such as friction, where the work done depends on the path, and energy is dissipated.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'How do you find the speed at the bottom of a rough slope?', 'Initial energy − work done against friction = final KE + PE.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the efficiency of a machine?', 'Useful work output ÷ work input.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'A 1000 kg car accelerates at 0.5 m/s² at 10 m/s against 400 N resistance. What power is used?', 'F = 1000 × 0.5 + 400 = 900 N; P = 900 × 10 = 9 kW.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the work done by gravity when an object moves horizontally?', 'Zero, since there is no vertical displacement.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the work done by a normal reaction force?', 'Zero, since it is perpendicular to the motion.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What happens to mechanical energy when there is air resistance?', 'It decreases; energy is transferred to heat and sound.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'How do you find the maximum extension of a spring when a mass is dropped onto it?', 'Equate the loss in GPE to the gain in EPE (and any KE).', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the modulus of elasticity λ?', 'The force required to double the length of a string or spring.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'What is the elastic potential energy for a spring with stiffness k?', '½kx².', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'How do you calculate average power over a journey?', 'Total work done ÷ total time.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.2', 'Work, Energy & Power', 'Can work done be negative?', 'Yes, when the force opposes the motion, e.g. friction.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is momentum?', 'Mass × velocity: p = mv (a vector).', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is impulse?', 'Force × time, or change in momentum: I = Ft = mv − mu.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the unit of impulse?', 'N s (equivalent to kg m/s).', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the impulse of a variable force?', 'I = ∫ F dt.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the principle of conservation of momentum?', 'The total momentum of a system is constant if no external forces act.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is Newton''s experimental law (law of restitution)?', 'Speed of separation = e × speed of approach.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the coefficient of restitution e?', 'A number between 0 and 1: e = 1 for perfectly elastic collisions, e = 0 for perfectly inelastic.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What happens in a perfectly inelastic collision?', 'The objects coalesce (stick together).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'Is kinetic energy conserved in a collision with e < 1?', 'No, kinetic energy is lost.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'A 2 kg ball at 3 m/s hits a 1 kg ball at rest and they coalesce. Find the final speed.', '6 = 3v, so v = 2 m/s.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'How do you find the loss in KE in a collision?', 'KE before − KE after.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the rebound speed of a ball hitting a wall at u with coefficient e?', 'eu.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'A ball is dropped from height h and rebounds with coefficient e. What height does it reach?', 'e²h.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is an oblique collision with a smooth wall?', 'The velocity component parallel to the wall is unchanged; the perpendicular component is multiplied by e and reversed.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'In an oblique collision between smooth spheres, what is conserved?', 'Momentum along the line of centres, and each sphere''s velocity perpendicular to the line of centres is unchanged.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the impulse on a ball of 0.2 kg that hits a wall at 10 m/s and rebounds at 8 m/s?', '0.2 × (8 − (−10)) = 3.6 N s.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What are successive collisions?', 'A series of collisions, such as a ball hitting another which then hits a third, analysed one at a time.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'How do you know if there will be a further collision?', 'Compare the velocities after the collisions to see whether one object catches up with another.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is impulse in 2D?', 'A vector: I = m(v − u).', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the effect of an explosion on momentum?', 'Momentum is conserved; if initially at rest, the fragments have equal and opposite momentum.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the recoil of a gun?', 'The gun moves backwards so that total momentum remains zero.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What does a large impulse over a short time mean?', 'A large force.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'Why do airbags reduce injury?', 'They increase the collision time, reducing the force for the same impulse.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the momentum of a 3 kg object at (2i − j) m/s?', '(6i − 3j) kg m/s.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the relationship between impulse and area under a force–time graph?', 'The impulse equals the area under the graph.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the direct impact of spheres?', 'A collision where velocities are along the line of centres.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'For e = 1, what happens when equal masses collide directly, one at rest?', 'They exchange velocities.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What is the maximum KE loss in a collision?', 'When e = 0 (the objects coalesce).', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'What does e depend on?', 'The materials of the colliding objects.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.3', 'Impulse & Momentum', 'How is the impulse between two colliding bodies related?', 'Equal and opposite by Newton''s third law.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is angular velocity?', 'The rate of change of angle: ω = dθ/dt, measured in rad/s.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the relationship between linear speed and angular speed?', 'v = rω.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the acceleration of an object in uniform circular motion?', 'v²/r = rω², directed towards the centre.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the centripetal force?', 'F = mv²/r = mrω², the resultant force towards the centre.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What provides the centripetal force for a car on a flat bend?', 'Friction between the tyres and the road.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the maximum speed of a car on a flat bend with friction coefficient μ?', 'μmg = mv²/r, so v = √(μgr).', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'Why are roads banked?', 'So the normal reaction has a horizontal component providing centripetal force, reducing reliance on friction.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the speed on a banked track with no friction?', 'tan θ = v²/(rg), so v = √(rg tan θ).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is a conical pendulum?', 'A particle on a string moving in a horizontal circle: T cos θ = mg and T sin θ = mrω².', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'How do you find the angle of a conical pendulum?', 'tan θ = rω²/g.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is motion in a vertical circle?', 'Circular motion where speed varies due to gravity; use energy conservation and F = mv²/r.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the condition for a particle on a string to complete a vertical circle?', 'Tension ≥ 0 at the top: v² ≥ gr at the top.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the condition for a bead on a smooth wire to complete a vertical circle?', 'Speed > 0 at the top (it can''t fall off).', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the tension at the bottom of a vertical circle?', 'T = mg + mv²/r.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the tension at the top of a vertical circle?', 'T = mv²/r − mg.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'How do you find the speed at any point of a vertical circle?', 'Use conservation of energy from a known point.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What happens when the tension in the string becomes zero?', 'The particle leaves the circular path and moves as a projectile.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What happens when a particle on the outside of a sphere loses contact?', 'The normal reaction becomes zero: mg cos θ = mv²/r.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the period of circular motion?', 'T = 2π/ω.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'Convert 30 rpm to rad/s.', '30 × 2π/60 = π rad/s.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'A 0.5 kg mass moves in a circle of radius 2 m at 4 m/s. Find the centripetal force.', '0.5 × 16/2 = 4 N.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is centrifugal force?', 'A fictitious outward force felt in a rotating frame; in an inertial frame only centripetal force is real.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the minimum speed at the bottom for a string to complete a vertical circle of radius r?', 'v² = 5gr at the bottom, so v = √(5gr).', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the tension at the bottom when the particle just completes the circle?', 'T = mg + m(5gr)/r = 6mg.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What forces act on a car going over a hump-backed bridge?', 'Weight downwards and the normal reaction upwards; mg − R = mv²/r.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the maximum speed at the top of a hump without leaving the road?', 'R = 0: v = √(gr).', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'Is velocity constant in uniform circular motion?', 'No; the speed is constant but the direction changes.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the angular speed of the Earth''s rotation?', '2π/(24 × 3600) ≈ 7.27 × 10⁻⁵ rad/s.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'How is circular motion analysed with vectors?', 'Position r = r(cos ωt i + sin ωt j), and differentiate to find velocity and acceleration.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.4', 'Circular Motion', 'What is the direction of velocity in circular motion?', 'Tangential to the circle.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is the centre of mass?', 'The point where the whole mass of a body can be considered to act.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you find the centre of mass of particles on a line?', 'x̄ = Σmx/Σm.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you find the centre of mass of particles in a plane?', 'x̄ = Σmx/Σm and ȳ = Σmy/Σm.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a uniform rod?', 'At its midpoint.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a uniform triangular lamina?', 'At the centroid, two-thirds along each median from the vertex.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a uniform semicircular lamina?', '4r/(3π) from the centre along the axis of symmetry.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a uniform semicircular arc?', '2r/π from the centre.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a solid hemisphere?', '3r/8 from the flat face.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a hollow hemisphere?', 'r/2 from the flat face.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a solid cone?', 'h/4 from the base.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Where is the centre of mass of a sector of angle 2α?', '2r sin α/(3α) from the centre.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you find the centre of mass of a composite lamina?', 'Split it into simple shapes, find each centre of mass, and use x̄ = Σmx/Σm.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you handle a hole in a lamina?', 'Treat the hole as negative mass and subtract.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How is the centre of mass found by integration for a lamina under y = f(x)?', 'x̄ = ∫xy dx/∫y dx and ȳ = ∫½y² dx/∫y dx.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How is the centre of mass of a solid of revolution found?', 'x̄ = ∫πy²x dx/∫πy² dx.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What happens when a lamina is suspended freely from a point?', 'It hangs with its centre of mass directly below the point of suspension.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you find the angle a suspended lamina makes with the vertical?', 'Use the horizontal and vertical distances of the centre of mass from the suspension point: tan θ = horizontal/vertical.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'When does an object on an inclined plane topple?', 'When the vertical line through its centre of mass falls outside its base.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'When does an object slide before toppling?', 'When friction becomes limiting (tan θ > μ) before the centre of mass passes the base edge.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is the centre of mass of a uniform rectangular lamina?', 'At the intersection of its diagonals.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How do you find the centre of mass of a framework of rods?', 'Treat each rod as a particle at its midpoint with mass proportional to its length.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Why is symmetry useful in centre of mass problems?', 'The centre of mass lies on any axis of symmetry.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Masses of 2 kg at x = 1 and 3 kg at x = 4. Find x̄.', '(2 + 12)/5 = 2.8.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is the condition for a body resting on a point to be in equilibrium?', 'The centre of mass is vertically above or below the point.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How is centre of mass related to moments?', 'The moment of the total mass at the centre of mass equals the sum of the moments of all parts.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is a uniform lamina?', 'A flat object with mass evenly distributed over its area.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is the centre of mass of a hollow cone?', 'h/3 from the base.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'How does adding a particle to a lamina change its centre of mass?', 'Recalculate using the lamina and particle as two masses.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'What is the centre of mass of a uniform circular arc of angle 2α?', 'r sin α/α from the centre.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'M1.5', 'Centres of Mass', 'Why can the centre of mass lie outside the body?', 'For shapes like rings or L-shapes, the balance point may be in empty space.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is a discrete random variable?', 'A variable that takes a countable set of values, each with a probability.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(X) for a discrete random variable?', 'Σ x P(X = x).', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(X²)?', 'Σ x² P(X = x).', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is Var(X)?', 'E(X²) − [E(X)]².', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(aX + b)?', 'aE(X) + b.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is Var(aX + b)?', 'a²Var(X).', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(X + Y)?', 'E(X) + E(Y), always.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is Var(X + Y) for independent X and Y?', 'Var(X) + Var(Y).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is Var(X − Y) for independent X and Y?', 'Var(X) + Var(Y).', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(g(X))?', 'Σ g(x) P(X = x).', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the discrete uniform distribution on 1 to n?', 'P(X = r) = 1/n, with mean (n + 1)/2 and variance (n² − 1)/12.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the geometric distribution?', 'The number of trials up to and including the first success: P(X = r) = (1 − p)^(r−1) p.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the mean of a geometric distribution?', '1/p.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the variance of a geometric distribution?', '(1 − p)/p².', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is P(X > r) for a geometric distribution?', '(1 − p)ʳ.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the negative binomial distribution?', 'The number of trials needed to get r successes.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the mean of a binomial B(n, p)?', 'np.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the variance of B(n, p)?', 'np(1 − p).', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the mode of a discrete distribution?', 'The value with the highest probability.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'How do you find an unknown probability k in a distribution table?', 'Use the fact that all probabilities sum to 1.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is a cumulative distribution function for a discrete variable?', 'F(x) = P(X ≤ x).', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the standard deviation?', 'The square root of the variance.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'If E(X) = 3 and Var(X) = 2, find E(2X − 1) and Var(2X − 1).', '5 and 8.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'If X ~ B(10, 0.4), find E(X) and Var(X).', '4 and 2.4.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is E(XY) for independent X and Y?', 'E(X)E(Y).', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What does independence mean for random variables?', 'The value of one doesn''t affect the probabilities of the other.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'Find E(X) if P(X = 1) = 0.2, P(X = 2) = 0.5, P(X = 3) = 0.3.', '0.2 + 1 + 0.9 = 2.1.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'Find Var(X) for the distribution above.', 'E(X²) = 0.2 + 2 + 2.7 = 4.9; Var = 4.9 − 4.41 = 0.49.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the sum of n independent identical variables'' variance?', 'nVar(X).', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.1', 'Discrete Random Variables', 'What is the difference between Var(2X) and Var(X₁ + X₂)?', 'Var(2X) = 4Var(X); Var(X₁ + X₂) = 2Var(X) for independent copies.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What does the Poisson distribution model?', 'The number of events in a fixed interval when events occur randomly, independently and at a constant average rate.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the Poisson probability formula?', 'P(X = r) = e^(−λ) λʳ/r!.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the mean of Po(λ)?', 'λ.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the variance of Po(λ)?', 'λ.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What are the conditions for a Poisson model?', 'Events occur singly, randomly, independently, and at a constant average rate.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How can you check whether data fit a Poisson distribution?', 'Check whether the mean and variance are approximately equal.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'If X ~ Po(3), find P(X = 2).', 'e^(−3) × 9/2 ≈ 0.224.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'If X ~ Po(2), find P(X = 0).', 'e^(−2) ≈ 0.135.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How do you find P(X ≥ 1)?', '1 − P(X = 0).', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How do you change the interval for a Poisson rate?', 'Scale λ proportionally, e.g. 3 per hour becomes 6 per 2 hours.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the sum of independent Poisson variables?', 'Po(λ₁ + λ₂).', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'When can a binomial be approximated by a Poisson?', 'When n is large and p is small, with λ = np.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'When can a Poisson be approximated by a normal?', 'When λ is large (e.g. > 10), using N(λ, λ) with a continuity correction.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'If X ~ Po(25), what normal approximation is used?', 'N(25, 25).', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What continuity correction is used for P(X ≤ 20) when approximating Po(25)?', 'P(Y < 20.5).', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How do you test a Poisson mean?', 'H₀: λ = λ₀; find the probability of the observed value or more extreme under Po(λ₀).', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is a critical region for a Poisson test?', 'The values of X whose total probability in the tail is at most the significance level.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'Why can''t the actual significance level be exactly 5% in a Poisson test?', 'The distribution is discrete.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is a Poisson process?', 'A model where events occur continuously and independently at a constant rate.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How is the Poisson related to the exponential distribution?', 'The time between events in a Poisson process is exponentially distributed.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'If calls arrive at 4 per hour, what is P(no calls in 30 minutes)?', 'λ = 2: e^(−2) ≈ 0.135.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the mode of a Poisson distribution?', 'The largest integer ≤ λ (or both λ and λ − 1 if λ is an integer).', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'Why might a Poisson model be unsuitable?', 'Events may cluster, or the rate may change over time.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'If X ~ Po(1.5), find P(X ≤ 1).', 'e^(−1.5)(1 + 1.5) ≈ 0.558.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the shape of a Poisson distribution for small λ?', 'Positively skewed.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What happens to the shape as λ increases?', 'It becomes more symmetrical, approaching a normal distribution.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'Give an example of a Poisson situation.', 'The number of emails received per hour, or the number of accidents at a junction per month.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is the recurrence relation for Poisson probabilities?', 'P(X = r + 1) = P(X = r) × λ/(r + 1).', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'How do you use cumulative Poisson tables?', 'Look up P(X ≤ x) for the given λ.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.2', 'Poisson Distribution', 'What is P(X = r) when r > λ for a Poisson?', 'Probabilities decrease as r increases beyond the mode.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the product moment correlation coefficient?', 'r = Sxy/√(SxxSyy), measuring linear association.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is Sxy?', 'Σ(x − x̄)(y − ȳ) = Σxy − (ΣxΣy)/n.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the least squares regression line of y on x?', 'y = a + bx, where b = Sxy/Sxx and a = ȳ − bx̄.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What does least squares mean?', 'The line minimises the sum of the squared vertical residuals.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is a residual?', 'The observed value minus the value predicted by the regression line.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the regression line of x on y used for?', 'Predicting x from y when y is the independent variable.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'When should the regression line of x on y be used?', 'When y is controlled or when estimating x from a given y where both are random.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the effect of coding on the PMCC?', 'Linear coding (scaling and shifting) doesn''t change r (except its sign if scaled by a negative).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the effect of coding on the regression line?', 'The line must be converted back using the coding formulas.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'How do you test for correlation using the PMCC?', 'H₀: ρ = 0; compare |r| with the critical value for n and the significance level.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What assumption is needed for a PMCC hypothesis test?', 'The data come from a bivariate normal distribution.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What does a residual plot show?', 'Whether a linear model is appropriate; random scatter suggests a good fit.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What does a pattern in residuals suggest?', 'The relationship may be non-linear.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is an influential point?', 'A point that strongly affects the regression line.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is an outlier in regression?', 'A point with a large residual.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is interpolation?', 'Predicting within the range of the data.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is extrapolation?', 'Predicting outside the range of the data, which may be unreliable.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is Spearman''s rank correlation coefficient?', 'rₛ = 1 − 6Σd²/(n(n² − 1)), measuring monotonic association using ranks.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'When is Spearman''s rank preferred to PMCC?', 'When data are ranked, not bivariate normal, or the relationship is monotonic but not linear.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'How are tied ranks handled in Spearman''s?', 'Give tied values the mean of the ranks they would occupy.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is a scatter diagram?', 'A plot of paired data points, used to see the relationship between variables.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What does r = 0 mean?', 'No linear correlation (there could still be a non-linear relationship).', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the coefficient of determination?', 'r², the proportion of variation in y explained by the linear model.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is a controlled variable?', 'A variable whose values are set by the experimenter, e.g. temperature in an experiment.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What is the residual sum of squares?', 'Σ(y − ŷ)², minimised by the least squares line.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'How do you calculate b if Sxy = 40 and Sxx = 20?', 'b = 2.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'If x̄ = 5, ȳ = 12 and b = 2, find a.', 'a = 12 − 10 = 2.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'Why doesn''t correlation imply causation?', 'A third factor or coincidence may explain the association.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'What does a negative Spearman''s rank coefficient indicate?', 'As one variable''s rank increases, the other''s tends to decrease.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.3', 'Bivariate Data', 'How do you choose between a one-tailed and two-tailed correlation test?', 'One-tailed if a specific direction (positive or negative) is suspected in advance; otherwise two-tailed.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is a chi-squared goodness of fit test?', 'A test of whether observed frequencies fit a proposed distribution.', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the chi-squared test statistic?', 'X² = Σ (O − E)²/E.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How are expected frequencies found in a goodness of fit test?', 'Total frequency × probability from the proposed distribution.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the condition on expected frequencies?', 'Each should be at least 5; combine classes if necessary.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How are degrees of freedom found for goodness of fit?', 'Number of classes (after combining) − 1 − number of parameters estimated from the data.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is a contingency table test?', 'A chi-squared test for independence between two categorical variables.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How are expected frequencies calculated in a contingency table?', '(Row total × column total) ÷ grand total.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How many degrees of freedom does an r × c contingency table have?', '(r − 1)(c − 1).', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is Yates'' continuity correction?', 'For 2×2 tables: Σ (|O − E| − 0.5)²/E.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What are the hypotheses for a test of independence?', 'H₀: the variables are independent; H₁: they are not independent (associated).', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'When do you reject H₀ in a chi-squared test?', 'When the test statistic exceeds the critical value.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'Is a chi-squared test one-tailed or two-tailed?', 'One-tailed (upper tail), since large values show poor fit.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What does a very small X² value suggest?', 'A very good fit, possibly suspiciously good.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How do you test whether data fit a binomial distribution with p estimated?', 'Estimate p from the data mean, calculate expected frequencies, and subtract an extra degree of freedom.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How do you test whether data fit a Poisson distribution?', 'Estimate λ from the sample mean (if unknown), find expected frequencies, and test with one fewer degree of freedom.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the critical value for χ² with 1 degree of freedom at 5%?', '3.841.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the critical value for χ² with 2 degrees of freedom at 5%?', '5.991.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How do you interpret a significant contingency table result?', 'Look at which cells have the largest contributions (O − E)²/E to describe the association.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the effect of combining classes?', 'It reduces the degrees of freedom.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'Can chi-squared tests be used with percentages?', 'No, only with observed frequencies.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the distribution of the test statistic under H₀?', 'Approximately χ² with the appropriate degrees of freedom.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is a uniform distribution test?', 'Testing whether all outcomes are equally likely, e.g. a fair die.', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'Find the expected frequency for a fair die rolled 120 times.', '20 for each face.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the shape of the χ² distribution?', 'Positively skewed, becoming more symmetrical as the degrees of freedom increase.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What is the mean of a χ² distribution with ν degrees of freedom?', 'ν.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What should the conclusion of a chi-squared test include?', 'Whether to reject H₀, stated in context.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'Why must observations be independent for a chi-squared test?', 'The test assumes each observation falls into a category independently.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What does a large contribution from one cell indicate?', 'That cell differs most from what would be expected under H₀.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'How do you test a normal distribution fit?', 'Group the data, calculate expected frequencies using normal probabilities, and subtract degrees of freedom for estimated μ and σ.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.4', 'Chi-Squared Tests', 'What does "goodness of fit" mean?', 'How well a theoretical distribution matches observed data.', 30),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is a non-parametric test?', 'A test that doesn''t assume a particular population distribution (e.g. normal).', 1),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'When are non-parametric tests used?', 'When data are not normally distributed, sample sizes are small, or data are ordinal.', 2),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What does a non-parametric test usually test?', 'The median rather than the mean.', 3),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the sign test?', 'A test for the median, based on counting values above and below the hypothesised median.', 4),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What distribution does the sign test use?', 'The binomial distribution B(n, 0.5) under H₀.', 5),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What happens to values equal to the hypothesised median in a sign test?', 'They are discarded and n is reduced.', 6),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the Wilcoxon signed-rank test?', 'A test for the median of a symmetric distribution, using the ranks of the differences from the hypothesised median.', 7),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How is the Wilcoxon signed-rank statistic calculated?', 'Rank the absolute differences, then sum the ranks of positive and negative differences separately; T is the smaller sum.', 8),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'When do you reject H₀ in a Wilcoxon signed-rank test?', 'When T is less than or equal to the critical value.', 9),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the Wilcoxon rank-sum (Mann–Whitney) test?', 'A test for whether two independent samples come from populations with the same median.', 10),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How is the rank-sum test statistic calculated?', 'Rank all observations together, then sum the ranks of the smaller sample.', 11),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What assumption does the Wilcoxon signed-rank test make?', 'The distribution is symmetric about the median.', 12),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the paired sign test?', 'A sign test on the differences between paired observations.', 13),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the advantage of Wilcoxon over the sign test?', 'It uses the size of the differences, not just their signs, so it is more powerful.', 14),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the disadvantage of non-parametric tests?', 'They are usually less powerful than parametric tests when parametric assumptions hold.', 15),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How is a normal approximation used for large samples in Wilcoxon tests?', 'The rank sum is approximately normal with a known mean and variance.', 16),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the mean of T in the Wilcoxon signed-rank test under H₀?', 'n(n + 1)/4.', 17),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the variance of T in the Wilcoxon signed-rank test under H₀?', 'n(n + 1)(2n + 1)/24.', 18),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How are ties in ranks handled?', 'Assign the average of the tied ranks.', 19),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the null hypothesis for a Wilcoxon signed-rank test?', 'The population median equals the hypothesised value.', 20),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the alternative hypothesis for a one-tailed sign test?', 'The median is greater than (or less than) the hypothesised value.', 21),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How does the sign test calculate a p-value?', 'Find P(X ≤ number of minority signs) using B(n, 0.5).', 22),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'Why is the sign test robust?', 'It is unaffected by outliers because only signs are used.', 23),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is ordinal data?', 'Data that can be ranked but not measured on a precise scale.', 24),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is a runs test?', 'A test for randomness, based on the number of runs of the same outcome in a sequence.', 25),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'When is a Mann–Whitney test used instead of a two-sample t-test?', 'When the populations can''t be assumed normal.', 26),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What does a small rank sum for one sample indicate?', 'That sample tends to have smaller values.', 27),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'How do you rank data from smallest to largest?', 'Give rank 1 to the smallest value, rank 2 to the next, and so on.', 28),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What is the relationship between parametric and non-parametric tests?', 'Parametric tests assume a distribution and test parameters; non-parametric tests make fewer assumptions.', 29),
  ('Further Mathematics', 'OCR B', 'alevel', 'S1.5', 'Non-Parametric Tests', 'What conclusion should a non-parametric test give?', 'Whether there is evidence the median differs, stated in context.', 30)
),
fresh AS (
  SELECT v.* FROM v
  WHERE NOT EXISTS (
    SELECT 1 FROM flashcards f
    WHERE f.subject = v.subject AND f.exam_board = v.exam_board AND f.level = v.level
      AND f.topic_id = v.topic_id AND f.front = v.front)
),
cur AS (
  SELECT subject, exam_board, level, topic_id, count(*) AS n, max(card_order) AS mx
  FROM flashcards
  WHERE subject = 'Further Mathematics' AND exam_board = 'OCR B' AND level = 'alevel'
  GROUP BY 1, 2, 3, 4
),
ranked AS (
  SELECT fr.*, coalesce(c.n, 0) AS n, coalesce(c.mx, 0) AS mx,
         row_number() OVER (PARTITION BY fr.topic_id ORDER BY fr.ord) AS rn
  FROM fresh fr
  LEFT JOIN cur c USING (subject, exam_board, level, topic_id)
)
INSERT INTO flashcards (subject, exam_board, topic_id, topic_name, front, back, card_order, level)
SELECT subject, exam_board, topic_id, topic_name, front, back, mx + rn, level
FROM ranked
WHERE n + rn <= 30;
